<template><q-page class="q-pa-lg"><div class="row items-center justify-between q-mb-lg"><div class="text-h4">Proizvođači</div><q-btn color="primary" icon="add" label="Dodaj" @click="open()"/></div><q-table :rows="items" :columns="columns" row-key="id_proizvodac"><template #body-cell-akcije="p"><q-td :props="p"><q-btn flat icon="edit" @click="open(p.row)"/><q-btn flat color="negative" icon="delete" @click="remove(p.row)"/></q-td></template></q-table><q-dialog v-model="dialog"><q-card style="min-width:420px"><q-card-section class="text-h6">{{form.id_proizvodac?'Uredi':'Dodaj'}} proizvođača</q-card-section><q-card-section class="q-gutter-md"><q-input v-model="form.naziv" label="Naziv" outlined/><q-input v-model="form.kontakt_osoba" label="Kontakt osoba" outlined/><q-input v-model="form.email" label="Email" outlined/><q-input v-model="form.telefon" label="Telefon" outlined/><q-input v-model="form.web" label="Web" outlined/></q-card-section><q-card-actions align="right"><q-btn flat label="Odustani" v-close-popup/><q-btn color="primary" label="Spremi" @click="save"/></q-card-actions></q-card></q-dialog></q-page></template>
<script setup>
import {onMounted,reactive,ref} from 'vue'; import {useQuasar} from 'quasar'; import {api} from 'boot/axios'; const $q=useQuasar(); const items=ref([]); const dialog=ref(false); const form=reactive({id_proizvodac:null,naziv:'',kontakt_osoba:'',email:'',telefon:'',web:''}); const columns=[{name:'naziv',label:'Naziv',field:'naziv',align:'left'},{name:'kontakt_osoba',label:'Kontakt',field:'kontakt_osoba'},{name:'email',label:'Email',field:'email'},{name:'telefon',label:'Telefon',field:'telefon'},{name:'akcije',label:'Akcije',field:'id_proizvodac'}]; async function load(){const r=await api.get('/proizvodaci');items.value=r.data.data||r.data;} function open(x=null){Object.assign(form,{id_proizvodac:x?.id_proizvodac||null,naziv:x?.naziv||'',kontakt_osoba:x?.kontakt_osoba||'',email:x?.email||'',telefon:x?.telefon||'',web:x?.web||''});dialog.value=true;} async function save(){try{if(form.id_proizvodac)await api.put(`/proizvodaci/${form.id_proizvodac}`,form);else await api.post('/proizvodaci',form);dialog.value=false;await load();}catch(e){$q.notify({type:'negative',message:e.response?.data?.message||'Greška pri spremanju.'});}} async function remove(x){if(!confirm(`Obrisati "${x.naziv}"?`))return;try{await api.delete(`/proizvodaci/${x.id_proizvodac}`);await load();}catch(e){$q.notify({type:'negative',message:e.response?.data?.message||'Brisanje nije moguće.'});}} onMounted(load);
</script>
